describe('r3 confirmed frozen projection browser controls', () => {
  it.each(['fabric', 'garment'] as const)('verifies native %s context, execute and recovered original ACK', async family => {
    const w = confirmedWire[family], command = parseDevelopmentCreateCommand(w.executeRequest), principal = w.executeResponse.result.actorId;
    await expect(verifyDevelopmentCreateOutcome(w.executeResponse.result, principal, command)).resolves.toMatchObject({ outcome: 'converted' });
    await expect(verifyDevelopmentCreateOutcome(w.recoverResponse.result, principal, command)).resolves.toMatchObject({ outcome: 'converted' });
    const f = fixture(principal); f.transport.mockResolvedValue(f.response(w.contextResponse.result)); await expect(f.service.context(command.source.id, command.parameters.selectedSource)).resolves.toBeTruthy();
  });
  it.each(['spec', 'composition', 'process', 'unit', 'missingProof', 'version', 'duplicateOrigin', 'sourceId', 'caseId', 'factory', 'profileFallback'])('rejects fully rehashed confirmed %s attack', async attack => {
    const w: any = copy(confirmedWire[attack === 'process' ? 'garment' : 'fabric']), r = w.executeResponse.result, command = parseDevelopmentCreateCommand(w.executeRequest), a = r.original.sourceAnchors, e = a.selectedResultEvidence;
    if (attack === 'spec') r.original.lines[0].record.specSnapshot.fabric.weightValue = 260;
    if (attack === 'composition') e.confirmedSpecSnapshot.fabric.composition = 'WRONG';
    if (attack === 'process') e.confirmedSpecSnapshot.garment.processSpec = 'WRONG';
    if (attack === 'unit') e.confirmedSpecSnapshot.fabric.weightUnit = 'gsm';
    if (attack === 'missingProof') e.confirmedSpecification.origins[0].evidenceAuditIds = [];
    if (attack === 'version') e.confirmedSpecification.origins[0].snapshot.version.updatedAt = 'unknown';
    if (attack === 'duplicateOrigin') e.confirmedSpecification.origins.push(copy(e.confirmedSpecification.origins[0]));
    if (attack === 'sourceId') e.confirmedSpecification.sourceId = 'OTHER';
    if (attack === 'caseId') e.confirmedSpecification.caseId = 'OTHER';
    if (attack === 'factory') e.confirmedSpecification.factoryRelationId = 'OTHER';
    if (attack === 'profileFallback') a.selectedResultEvidence = null;
    const { contentFingerprint, ...basis } = e.confirmedSpecification;
    e.confirmedSpecification.contentFingerprint = await conversionClientDigest(basis);
    command.source.expected.contentFingerprint = await conversionClientDigest(a); r.original.input = command;
    r.commandHash = await conversionClientDigest({ protocol: 'order_conversion_command_v1', actorId: r.actorId, input: command });
    await expect(verifyDevelopmentCreateOutcome(await signed(r), r.actorId, command)).rejects.toBeTruthy();
  });
});

