describe('r4 actual target-preserving link wire', () => {
  it('verifies link context and unchanged actual target, lines, stages and recover ACK', async () => {
    const command = parseDevelopmentConversionCommand(linkWire.executeRequest), principal = linkWire.executeResponse.result.actorId;
    await expect(verifyDevelopmentConversionOutcome(linkWire.executeResponse.result, principal, command)).resolves.toMatchObject({ outcome: 'linked' });
    await expect(verifyDevelopmentConversionOutcome(linkWire.recoverResponse.result, principal, command)).resolves.toMatchObject({ outcome: 'linked' });
    if (command.operation !== 'development_link') throw new Error('fixture'); const f = fixture(principal); f.transport.mockResolvedValue(f.response(linkWire.contextResponse.result));
    await expect(f.service.contextLink(command.source.id, command.parameters.orderId, command.parameters.selectedSource)).resolves.toMatchObject({ selection: { operation: 'development_link' } });
  });
  it('preserves a migrated legacy integer header when linking an unchanged old order', async () => {
    const r: any = copy(linkWire.executeResponse.result), command = parseDevelopmentConversionCommand(copy(linkWire.executeRequest)), o = r.original;
    if (command.operation !== 'development_link') throw new Error('fixture');
    o.orderBefore.record.unit = null; o.orderAfter.record.unit = null;
    command.parameters.expectedTarget.contentFingerprint = await conversionClientDigest({ order: o.orderBefore, ...o.targetBefore });
    o.input = command;
    r.commandHash = await conversionClientDigest({ protocol: 'order_conversion_command_v1', actorId: r.actorId, input: command });
    await expect(verifyDevelopmentConversionOutcome(await signed(r), r.actorId, command)).resolves.toMatchObject({ outcome: 'linked' });
  });
  it.each(['order', 'line', 'stage', 'targetVersion', 'targetFingerprint', 'customer', 'wrongOrder', 'targetMissing', 'duplicate'])('rejects rehashed target %s mutation', async attack => {
    const command = parseDevelopmentConversionCommand(copy(linkWire.executeRequest)), r: any = copy(linkWire.executeResponse.result);
    if (attack === 'order') r.original.orderAfter.record.quoteAmount = '999';
    if (attack === 'line') r.original.lines[0].record.quantity = '999';
    if (attack === 'stage') r.original.productionStages[0].record.status = 'pending';
    if (attack === 'targetVersion') r.original.orderBefore.record.updatedAt = '999';
    if (attack === 'targetFingerprint') r.original.targetBefore.lines[0].record.quantity = '999';
    if (attack === 'customer') { r.original.orderBefore.record.customerRelationId = 'another'; r.original.orderAfter.record.customerRelationId = 'another'; }
    if (attack === 'wrongOrder') r.orderId = 'another';
    if (attack === 'targetMissing') r.original.targetBefore = null;
    if (attack === 'duplicate') r.original.lines.push(copy(r.original.lines[0]));
    await expect(verifyDevelopmentConversionOutcome(await signed(r), r.actorId, command)).rejects.toBeTruthy();
  });
  it('persists original link and recovers before retry; cancel committed returns linked ACK', async () => {
    const command = parseDevelopmentConversionCommand(linkWire.executeRequest), f = fixture(linkWire.executeResponse.result.actorId);
    f.transport.mockRejectedValueOnce(new Error('timeout')); await expect(f.service.execute(command)).rejects.toThrow(); expect(f.service.pending()?.input).toEqual(command);
    f.transport.mockResolvedValueOnce(f.response(linkWire.recoverResponse.result)); await expect(f.service.execute(command)).resolves.toMatchObject({ outcome: 'linked' }); expect(f.service.pending()).toBeNull();
    const g = fixture(linkWire.executeResponse.result.actorId); g.transport.mockRejectedValueOnce(new Error('timeout')); await expect(g.service.execute(command)).rejects.toThrow();
    g.transport.mockResolvedValueOnce(g.response(linkWire.recoverResponse.result)); await expect(g.service.cancel()).resolves.toMatchObject({ outcome: 'linked' }); expect(g.service.pending()).toBeNull();
  });
  it('context target change invalidates the prepared target identity', async () => {
    const command = parseDevelopmentConversionCommand(linkWire.executeRequest); if (command.operation !== 'development_link') throw new Error('fixture'); const f = fixture(linkWire.executeResponse.result.actorId);
    const ctx = copy(linkWire.contextResponse.result); ctx.defaults.expectedTarget.contentFingerprint = 'a'.repeat(64); f.transport.mockResolvedValueOnce(f.response(ctx));
    await expect(f.service.contextLink(command.source.id, command.parameters.orderId, command.parameters.selectedSource)).rejects.toBeTruthy();
  });
});

describe('transport and stored-original recovery boundaries', () => {
  it('native AbortSignal timeout leaves original pending, retry first recovers', async () => {
    vi.useFakeTimers(); try {
      const f = fixture(actor, 10); f.transport.mockImplementationOnce((_url, init) => new Promise((_resolve, reject) => init.signal.addEventListener('abort', () => reject(new DOMException('Timed out', 'AbortError')), { once: true })));
      const result = f.service.execute(input()), assertion = expect(result).rejects.toMatchObject({ name: 'AbortError' }); await vi.advanceTimersByTimeAsync(10); await assertion; expect(f.service.pending()?.input).toEqual(input());
      f.transport.mockResolvedValueOnce(f.response(ack())); await f.service.execute(input()); expect(f.transport.mock.calls[1][0]).toMatch(/recover$/);
    } finally { vi.useRealTimers(); }
  });
  it('a fresh service instance resumes the same session original without a new key or secrets', async () => {
    const f = fixture(); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.service.execute(input())).rejects.toThrow();
    const persisted = [...f.memory.values()][0]; expect(persisted).not.toContain('Bearer'); expect(persisted).not.toContain('private-test-token');
    const next = createOrderConversionCommandService({ principal: () => ({ actorId: actor, endpoint: '/api', generation: 'reload', headers: { Authorization: 'Bearer replacement-token' } }), storage: f.storage, fetch: vi.fn().mockResolvedValue(f.response(ack())) });
    await expect(next.recover()).resolves.toMatchObject({ outcome: 'converted' }); expect(next.pending()).toBeNull();
  });
  it('a verified legacy result is preserved as unverified and cannot retire pending', async () => {
    const f = fixture(); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.service.execute(input())).rejects.toThrow();
    const r: any = await unconfirmed(); r.outcome = 'legacy_unverified'; r.legacyOrderId = 'OLD'; r.legacyProof = { source: { id: input().source.id, record: { id: input().source.id } }, order: { id: 'OLD', record: { id: 'OLD', sourceCaseId: input().source.id, clientRequestId: input().requestKey } }, businessAudit: { id: 'AUDIT-OLD', record: { id: 'AUDIT-OLD', actorId: actor, action: 'convert_dev_case', targetType: 'DevelopmentCase', targetId: input().source.id, detail: { after: { orderId: 'OLD' } } } } };
    f.transport.mockResolvedValueOnce(f.response(r)); await expect(f.service.recover()).resolves.toMatchObject({ outcome: 'legacy_unverified' }); expect(f.service.pending()).not.toBeNull();
  });
  it.each(['version', 'quantityCapabilities', 'defaults'])('rejects prepared context %s drift', async attack => {
    const f = fixture(); const r: any = copy(wire.contextResponse.result);
    if (attack === 'version') r.source.expected.quotationVersion = 1;
    if (attack === 'quantityCapabilities') r.quantityCapabilities.supportsFractional = true;
    if (attack === 'defaults') r.defaults.millRelationId = 'other';
    f.transport.mockResolvedValueOnce(f.response(r)); await expect(f.service.context(input().source.id, input().parameters.selectedSource)).rejects.toBeTruthy(); expect(f.service.pending()).toBeNull();
  });
});

