function quoteFixture() {
  const f = fixture(); const service = createQuotationConversionCommandService({ principal: () => ({ actorId: quoteWire.executeResponse.result.actorId, endpoint: '/api', generation: 'q1', headers: { Authorization: 'Bearer quote-private' } }), storage: f.storage, fetch: f.transport as any }); return { ...f, service };
}
async function rehashQuote(r: any, command: any) {
  command.source.expected.contentFingerprint = await conversionClientDigest(r.original.sourceAnchors); r.original.input = command;
  r.commandHash = await conversionClientDigest({ protocol: 'order_conversion_command_v1', actorId: r.actorId, input: command }); return signed(r);
}
async function modernQuoteAck(options: { mixed?: boolean; large?: boolean } = {}) {
  const r: any = copy(quoteWire.executeResponse.result), command = parseQuotationCreateCommand(copy(quoteWire.executeRequest)), o = r.original, anchors = o.sourceAnchors;
  const q = anchors.quotationLines[0].record, line = o.lines[0].record;
  const firstQuantity = options.large ? '2147483648' : '1000.25', firstAmount = options.large ? '21474836480' : '10002.5';
  q.quantity = firstQuantity; q.amount = firstAmount; line.quantity = firstQuantity; line.netValue = firstAmount;
  let total = firstAmount;
  if (options.mixed) {
    const q2 = copy(anchors.quotationLines[0]), line2 = copy(o.lines[0]);
    q2.id += '-two'; q2.record.id = q2.id; q2.record.lineNumber = 2; q2.record.fabricCode = 'FABRIC-2'; q2.record.description = 'Mixed-unit second line'; q2.record.quantity = '2.5'; q2.record.unit = 'M'; q2.record.unitPrice = '4'; q2.record.amount = '10';
    line2.id += '-two'; line2.record.id = line2.id; line2.record.lineNumber = 2; line2.record.materialCode = 'FABRIC-2'; line2.record.description = 'Mixed-unit second line'; line2.record.quantity = '2.5'; line2.record.unit = 'M'; line2.record.unitPrice = '4'; line2.record.netValue = '10';
    anchors.quotationLines.push(q2); o.lines.push(line2); total = options.large ? '21474836490' : '10012.5';
    o.orderAfter.record.quantity = null; o.orderAfter.record.unit = null;
  } else { o.orderAfter.record.quantity = firstQuantity; o.orderAfter.record.unit = 'PC'; }
  for (const source of [o.sourceBefore.record, anchors.source.record, o.sourceAfter.record]) source.totalAmount = total;
  o.orderAfter.record.quoteAmount = total;
  return { ack: await rehashQuote(r, command), command };
}
describe('qualified quote command browser service', () => {
  it('checks actual Quote27 context, actual complete ACK and recovered original ACK', async () => {
    const command = parseQuotationCreateCommand(quoteWire.executeRequest), actor = quoteWire.executeResponse.result.actorId;
    await expect(verifyQuotationConversionOutcome(quoteWire.executeResponse.result, actor, command)).resolves.toMatchObject({ outcome: 'converted' });
    await expect(verifyQuotationConversionOutcome(quoteWire.recoveryResponse.result, actor, command)).resolves.toMatchObject({ outcome: 'converted' });
    const f = quoteFixture(); f.transport.mockResolvedValueOnce(f.response(quoteWire.contextResponse.result)); await expect(f.service.contextQuotation(command.source.id, quoteWire.contextRequest.overrides as any)).resolves.toMatchObject({ preparation: { state: 'prepared' } }); expect(f.transport.mock.calls[0][0]).toBe('/api/v1/quotations/' + encodeURIComponent(command.source.id) + '/convert-command/context');
  });
  it('accepts a complete new quotation receipt with an explicitly unrecorded delivery date', async () => {
    // Construct the current no-date contract from the fixed capture without
    // changing its source, quantity, price, authority or original audit facts.
    const r: any = copy(quoteWire.executeResponse.result), command = parseQuotationCreateCommand(copy(quoteWire.executeRequest));
    command.parameters.dueDate = null;
    r.original.orderAfter.record.dueDate = '';
    expect(r.original.sourceBefore.record.validUntil).toBe('2026-10-30');
    await expect(verifyQuotationConversionOutcome(await rehashQuote(r, command), r.actorId, command)).resolves.toMatchObject({ outcome: 'converted' });
  });
  it('accepts the current decimal and mixed-unit capability contract', async () => {
    const f = quoteFixture(), command = parseQuotationCreateCommand(quoteWire.executeRequest), context = copy(quoteWire.contextResponse.result);
    context.quantityCapabilities = { protocol: 'decimal18_4', writeSchema: 'decimal18_4', supportsFractional: true, mixedQuotationUnits: true, supportedUnits: ['M', 'YD', 'KG', 'G', 'PC', 'SET', 'ROLL', 'DOZEN'] };
    f.transport.mockResolvedValueOnce(f.response(context));
    await expect(f.service.contextQuotation(command.source.id, quoteWire.contextRequest.overrides as any)).resolves.toMatchObject({ quantityCapabilities: context.quantityCapabilities });
  });
  it('retains a legacy unrecorded-date receipt bound to its original quotation validity date', async () => {
    const r: any = copy(quoteWire.executeResponse.result), command = parseQuotationCreateCommand(copy(quoteWire.executeRequest));
    command.parameters.dueDate = null;
    r.original.orderAfter.record.dueDate = r.original.sourceBefore.record.validUntil;
    await expect(verifyQuotationConversionOutcome(await rehashQuote(r, command), r.actorId, command)).resolves.toMatchObject({ outcome: 'converted' });
  });
  it.each([
    { requested: null, actual: '2027-01-01' },
    { requested: null, actual: null },
    { requested: '2026-11-20', actual: '' },
    { requested: '2026-11-20', actual: '2026-10-30' },
  ])('rejects a rehashed receipt with requested date $requested and unrelated actual date $actual', async ({ requested, actual }) => {
    const r: any = copy(quoteWire.executeResponse.result), command = parseQuotationCreateCommand(copy(quoteWire.executeRequest));
    command.parameters.dueDate = requested;
    r.original.orderAfter.record.dueDate = actual;
    await expect(verifyQuotationConversionOutcome(await rehashQuote(r, command), r.actorId, command)).rejects.toMatchObject({ code: 'UNVERIFIED_REPLY' });
  });
  it('verifies exact fractional single-unit and mixed-unit conversion receipts', async () => {
    const actor = quoteWire.executeResponse.result.actorId, single = await modernQuoteAck();
    await expect(verifyQuotationConversionOutcome(single.ack, actor, single.command)).resolves.toMatchObject({ outcome: 'converted' });
    const mixed = await modernQuoteAck({ mixed: true });
    await expect(verifyQuotationConversionOutcome(mixed.ack, actor, mixed.command)).resolves.toMatchObject({ outcome: 'converted' });
    mixed.ack.original.orderAfter.record.quantity = '1002.75'; mixed.ack.original.orderAfter.record.unit = 'PC';
    await expect(verifyQuotationConversionOutcome(await signed(mixed.ack), actor, mixed.command)).rejects.toBeTruthy();
  });
  it('accepts exact quantities above the old Int32 ceiling with the current decimal header', async () => {
    const actor = quoteWire.executeResponse.result.actorId, large = await modernQuoteAck({ large: true });
    await expect(verifyQuotationConversionOutcome(large.ack, actor, large.command)).resolves.toMatchObject({ outcome: 'converted' });
  });
  it('rejects internally inconsistent quantity capability declarations', async () => {
    const f = quoteFixture(), command = parseQuotationCreateCommand(quoteWire.executeRequest), context = copy(quoteWire.contextResponse.result);
    context.quantityCapabilities = { ...context.quantityCapabilities, writeSchema: 'decimal18_4', supportsFractional: false, mixedQuotationUnits: true };
    f.transport.mockResolvedValueOnce(f.response(context));
    await expect(f.service.contextQuotation(command.source.id, quoteWire.contextRequest.overrides as any)).rejects.toBeTruthy();
  });
  it('uses exact company v1 quotation routes for execute, recovery and committed cancellation', async () => {
    const command = parseQuotationCreateCommand(quoteWire.executeRequest);
    for (const action of ['execute', 'recover', 'cancel'] as const) {
      const f = quoteFixture();
      if (action !== 'execute') { f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.service.execute(command)).rejects.toThrow(); }
      f.transport.mockResolvedValueOnce(f.response(quoteWire.executeResponse.result));
      if (action === 'execute') await f.service.execute(command); else await f.service[action]();
      expect(f.transport.mock.calls.at(-1)![0]).toBe('/api/v1/quotations/' + encodeURIComponent(command.source.id) + '/convert-command/' + action);
    }
  });
  it.each(['quantity', 'unit', 'price', 'description', 'amount', 'PO', 'dueDate', 'payment', 'factoryID', 'factoryName', 'sourceVersion', 'sourcePointer', 'inheritedType', 'audit', 'stage', 'moq', 'mixedUnits'])('rejects rehashed quote %s attack', async attack => {
    const r: any = copy(quoteWire.executeResponse.result), command = parseQuotationCreateCommand(copy(quoteWire.executeRequest)), o = r.original, line = o.lines[0].record;
    if (attack === 'quantity') line.quantity = '999'; if (attack === 'unit') line.unit = 'M'; if (attack === 'price') line.unitPrice = 999;
    if (attack === 'description') line.description = 'WRONG'; if (attack === 'amount') line.netValue = 999; if (attack === 'PO') o.orderAfter.record.poNumber = 'WRONG';
    if (attack === 'dueDate') o.orderAfter.record.dueDate = '2027-01-01'; if (attack === 'payment') o.orderAfter.record.paymentInstrument = 'L/C'; if (attack === 'factoryID') o.orderAfter.record.millRelationId = 'WRONG'; if (attack === 'factoryName') o.orderAfter.record.millName = 'WRONG';
    if (attack === 'sourceVersion') o.sourceBefore.record.version = 999; if (attack === 'sourcePointer') o.sourceAfter.record.convertedOrderId = 'WRONG'; if (attack === 'inheritedType') { command.parameters.type = null; o.orderAfter.record.type = 'Fabric'; } if (attack === 'audit') o.businessAudits.pop(); if (attack === 'stage') o.productionStages.pop();
    if (attack === 'moq') o.orderAfter.record.moqSnapshot.garmentDefaultMoq = 999;
    if (attack === 'mixedUnits') { const q = copy(o.sourceAnchors.quotationLines[0]), l = copy(o.lines[0]); q.id += '-two'; q.record.id = q.id; q.record.lineNumber = 2; q.record.unit = 'M'; l.id += '-two'; l.record.id = l.id; l.record.lineNumber = 2; l.record.unit = 'M'; o.sourceAnchors.quotationLines.push(q); o.lines.push(l); o.orderAfter.record.quantity = '2000'; }
    await expect(verifyQuotationConversionOutcome(await rehashQuote(r, command), r.actorId, command)).rejects.toBeTruthy();
  });
  it('accepts the exact order type derived from immutable quotation rows when type is inherited', async () => {
    const r: any = copy(quoteWire.executeResponse.result), command = parseQuotationCreateCommand(copy(quoteWire.executeRequest)); command.parameters.type = null;
    await expect(verifyQuotationConversionOutcome(await rehashQuote(r, command), r.actorId, command)).resolves.toMatchObject({ outcome: 'converted' });
  });
  it('retains a valid historical full MOQ source snapshot unchanged', async () => {
    const r: any = copy(quoteWire.executeResponse.result), command = parseQuotationCreateCommand(copy(quoteWire.executeRequest)), snapshot = { fabricDefaultMoq: 777, garmentDefaultMoq: 150, capsuleMoq: 18, historicalMarker: 'keep entire source object' };
    r.original.sourceBefore.record.moqSnapshot = snapshot; r.original.sourceAnchors.source = copy(r.original.sourceBefore); r.original.sourceAnchors.moq.snapshot = snapshot; r.original.sourceAnchors.moq.config = null; r.original.orderAfter.record.moqSnapshot = snapshot;
    r.original.sourceAnchors.moq.basisFingerprint = await conversionClientDigest({ kind: 'source_snapshot', sourceId: command.source.id, snapshot });
    await expect(verifyQuotationConversionOutcome(await rehashQuote(r, command), r.actorId, command)).resolves.toMatchObject({ outcome: 'converted' });
  });
  it('quote retry recovers original full key and overrides, without another execution', async () => {
    const f = quoteFixture(), command = parseQuotationCreateCommand(quoteWire.executeRequest); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.service.execute(command)).rejects.toThrow(); expect(f.service.pending()?.input).toEqual(command);
    f.transport.mockResolvedValueOnce(f.response(quoteWire.recoveryResponse.result)); await f.service.execute(command); expect(f.transport.mock.calls.map(x => x[0].split('/').pop())).toEqual(['execute', 'recover']); expect(f.service.pending()).toBeNull();
  });
  it('factory rejects a cross-family cached body and cannot borrow its ACK', async () => {
    const f = quoteFixture(), command = parseQuotationCreateCommand(quoteWire.executeRequest); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.service.execute(command)).rejects.toThrow();
    const key = [...f.memory.keys()][0], pending = JSON.parse(f.memory.get(key)!); pending.input = input(); f.memory.set(key, JSON.stringify(pending)); await expect(f.service.recover()).rejects.toMatchObject({ code: 'CORRUPT_PENDING' }); expect(f.transport).toHaveBeenCalledTimes(1);
  });
  it('cancel after actual quote commit returns original ACK without undoing the order', async () => {
    const f = quoteFixture(), command = parseQuotationCreateCommand(quoteWire.executeRequest); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.service.execute(command)).rejects.toThrow(); f.transport.mockResolvedValueOnce(f.response(quoteWire.recoveryResponse.result)); await expect(f.service.cancel()).resolves.toMatchObject({ outcome: 'converted', orderId: quoteWire.executeResponse.result.orderId }); expect(f.service.pending()).toBeNull();
  });
});
